import type { Dungeon, EnemyAbility } from './enemies.ts'
import murd from './midnight_s2/murd.json'
import nalo from './midnight_s2/nalo.json'
import vale from './midnight_s2/vale.json'
import voidscar from './midnight_s2/void.json'
import fang from './midnight_s2/fang.json'
import rlp from './midnight_s2/rlp.json'
import tos from './midnight_s2/tos.json'
import kr from './midnight_s2/kr.json'

/**
 * A dungeon's abilities as generated by `yarn write`, with grimoire values already resolved —
 * the app never loads grimoire's spell table itself.
 */
export interface DungeonAbilitiesFile {
  /** The grimoire-wow version the values were resolved against. */
  grimoire: string
  abilities: EnemyAbility[]
}

const abilities = (file: { abilities: unknown[] }) => file.abilities as EnemyAbility[]

export const dungeons = (
  [
    {
      key: 'murd',
      name: 'Murder Row',
      abilities: abilities(murd),
      icon: 'inv_achievement_dungeon_murderrow',
    },
    {
      key: 'nalo',
      name: 'Den of Nalorakk',
      abilities: abilities(nalo),
      icon: 'inv_achievement_dungeon_proveyourworth',
    },
    {
      key: 'vale',
      name: 'The Blinding Vale',
      abilities: abilities(vale),
      icon: 'inv_achievement_dungeon_lightbloom',
    },
    {
      key: 'void',
      name: 'Voidscar Arena',
      abilities: abilities(voidscar),
      icon: 'inv_achievement_dungeon_voidscararena',
    },
    {
      key: 'fang',
      name: 'Altar of Fangs',
      abilities: abilities(fang),
      icon: 'inv_achievement_dungeon_altaroffangs',
    },
    {
      key: 'rlp',
      name: 'Ruby Life Pools',
      abilities: abilities(rlp),
      icon: 'achievement_dungeon_lifepools',
    },
    {
      key: 'tos',
      name: 'Temple of Sethraliss',
      abilities: abilities(tos),
      icon: 'achievement_dungeon_templeofsethraliss',
    },
    {
      key: 'kr',
      name: "Kings' Rest",
      abilities: abilities(kr),
      icon: 'achievement_dungeon_kingsrest',
    },
  ] as Dungeon[]
).sort((a, b) => a.key.localeCompare(b.key))

dungeons.push({
  key: 'all_dungeons',
  name: 'All dungeons',
  abilities: dungeons.flatMap(({ abilities }) => abilities),
  icon: 'achievement_challengemode_arakkoaspires_gold',
})
